  const payable=db.suppliers.reduce((sum,c)=>sum+Math.max(0,Number(c.openingBalance||0)+db.purchases.filter(s=>s.supplier===c.name&&s.payment==='Credit').reduce((a,z)=>a+Number(z.total||0),0)-db.supplierPayments.filter(p=>p.supplier===c.name).reduce((a,z)=>a+Number(z.amount||0),0)-db.supplierReturns.filter(r=>r.status!=='Cancelled'&&r.supplier===c.name&&r.method==='Credit Adjustment').reduce((a,z)=>a+Number(z.total||0),0)),0);
  const cashTotal=db.accounts.reduce((a,x)=>a+Number(x.balance||0),0), low=db.products.filter(x=>Number(x.qty||0)<=Number(x.minimumQty||0));
