function customerPreviousBalance(name){if(!name||name==='Cash Customer')return 0;const c=db.customers.find(x=>x.name===name),opening=Number(c?.openingBalance||0),credit=db.sales.filter(s=>s.status!=='Cancelled'&&s.customer===name&&s.payment==='Credit').reduce((a,s)=>a+Number(s.total||0),0),paid=db.customerPayments.filter(p=>p.customer===name).reduce((a,p)=>a+Number(p.amount||0),0),ret=db.customerReturns.filter(r=>r.status!=='Cancelled'&&r.customer===name&&r.method==='Credit Adjustment').reduce((a,r)=>a+Number(r.total||0),0);return Math.max(0,opening+credit-paid-ret)}
