 for(const l of lines){if(!db.products.find(x=>x.name===l.product))return alert('Product not found: '+l.product);if(!Number.isFinite(Number(l.qty))||Number(l.qty)<1||!Number.isFinite(Number(l.cost))||Number(l.cost)<0)return alert('Invalid quantity or purchase price for '+l.product);}
