 const paid=Math.min(total,paidInput);
 const selectedPayment=document.getElementById('ppay')?.value||'Credit';
 if(selectedPayment==='Cash'&&Math.abs(paid-total)>0.005)return alert('For Cash purchase, Paid Now must equal the full bill total.');
