function renderSalesHistory(){
 const groups={}, order=[];
 db.sales.forEach((x,i)=>{const key=x.invoice||x.id||('SALE-'+i);if(!groups[key]){groups[key]={invoice:key,items:[],firstIndex:i};order.push(key)}groups[key].items.push(x)});
 const rows=order.reverse().map(key=>{
  const g=groups[key], items=g.items, first=items[0], active=items.filter(x=>x.status!=='Cancelled'), cancelled=active.length===0;
  const total=active.reduce((a,x)=>a+Number(x.total||0),0);
  const paid=first.customer&&first.customer!=='Cash Customer'?db.customerPayments.filter(p=>p.customer===first.customer&&p.sourceInvoice===g.invoice).reduce((a,p)=>a+Number(p.amount||0),0):(first.payment==='Cash'?total:0);
  const previous=first.customer&&first.customer!=='Cash Customer'?customerPreviousBalance(first.customer):0;
  const outstanding=Math.max(0,previous+total-paid);
  const products=[...new Set(items.map(x=>x.product))].join(', ');
  const search=(`${g.invoice} ${first.customer||'Cash Customer'} ${first.saleType||'Retail'} ${products}`).replace(/"/g,'&quot;');
  return `<tr data-search="${search}" ondblclick='openInvoiceDetails(${JSON.stringify(g.invoice)})' title="Double-tap to view invoice"><td>${fmtDate(first.date)}</td><td><b>${g.invoice}</b></td><td>${first.customer||'Cash Customer'}</td><td>${first.saleType||'Retail'}</td><td>${active.length}</td><td>${money(total)}</td><td>${money(paid)}</td><td>${money(outstanding)}</td><td>${cancelled?'Cancelled':'Active'}</td><td><button class="secondary" onclick="event.stopPropagation();printInvoice(${g.firstIndex})">🖨️ Print</button>${cancelled?'':' <button class="danger" onclick="event.stopPropagation();cancelSale('+g.firstIndex+')">Cancel Invoice</button>'}</td></tr>`;
 }).join('');
 return `<table><tr><th>Date / Time</th><th>Invoice</th><th>Customer</th><th>Type</th><th>Items</th><th>Total</th><th>Paid</th><th>Outstanding</th><th>Status</th><th>Actions</th></tr>${rows||'<tr><td colspan="10">No sales yet</td></tr>'}</table>`;
}

function closeInvoiceDetails(){const m=document.getElementById('invoiceDetailsModal');if(m)m.remove()}
function openInvoiceDetails(invoice){
 const items=db.sales.filter(s=>s.invoice===invoice); if(!items.length)return;
 const first=items[0],active=items.filter(s=>s.status!=='Cancelled'),total=active.reduce((a,s)=>a+Number(s.total||0),0),discount=active.reduce((a,s)=>a+Number(s.discount||0),0),subtotal=total+discount;
 let previous=0,today=total,paid=0,outstanding=0;
 if(first.customer&&first.customer!=='Cash Customer'){
  const customer=first.customer, d=new Date(first.date), day=d.toISOString().slice(0,10), opening=Number((db.customers.find(c=>c.name===customer)||{}).openingBalance||0);
  const priorSales=db.sales.filter(s=>s.status!=='Cancelled'&&s.customer===customer&&s.payment==='Credit'&&s.invoice!==invoice&&new Date(s.date)<d).reduce((a,s)=>a+Number(s.total||0),0);
  const priorPayments=db.customerPayments.filter(p=>p.customer===customer&&new Date(p.date)<d).reduce((a,p)=>a+Number(p.amount||0),0);
  const priorReturns=db.customerReturns.filter(r=>r.status!=='Cancelled'&&r.customer===customer&&r.method==='Credit Adjustment'&&new Date(r.date)<d).reduce((a,r)=>a+Number(r.total||0),0);
  previous=Math.max(0,opening+priorSales-priorPayments-priorReturns);
  today=db.sales.filter(s=>s.status!=='Cancelled'&&s.customer===customer&&s.payment==='Credit'&&String(s.date||'').slice(0,10)===day).reduce((a,s)=>a+Number(s.total||0),0);
  paid=db.customerPayments.filter(p=>p.customer===customer&&String(p.date||'').slice(0,10)===day).reduce((a,p)=>a+Number(p.amount||0),0);
  if(first.payment==='Cash')paid+=total;
  outstanding=Math.max(0,previous+today-paid);
 }else{paid=first.payment==='Cash'?total:0;outstanding=0}
 const rows=active.map(s=>`<tr><td>${s.product}</td><td>${s.qty}</td><td>${money(s.unitPrice)}</td><td>${money(s.discount||0)}</td><td>${money(s.total||0)}</td></tr>`).join('');
 const modal=document.createElement('div');modal.id='invoiceDetailsModal';modal.className='invoice-modal';modal.innerHTML=`<div class="invoice-modal-card"><div class="invoice-modal-head"><div><h2>Invoice ${invoice}</h2><div>${fmtDate(first.date)}</div></div><button class="danger" onclick="closeInvoiceDetails()">✕</button></div><div class="invoice-modal-info"><b>Customer:</b> ${first.customer||'Cash Customer'}<br><b>Sale Type:</b> ${first.saleType||'Retail'}<br><b>Payment:</b> ${first.payment||'Cash'}${first.payment==='Cash'?' — '+accountName(first.accountId):''}</div><table><tr><th>Item</th><th>Qty</th><th>Unit Price</th><th>Discount</th><th>Total</th></tr>${rows||'<tr><td colspan="5">Invoice cancelled</td></tr>'}</table><div class="invoice-modal-summary"><div><span>Sub Total</span><b>${money(subtotal)}</b></div><div><span>Today Total</span><b>${money(today)}</b></div><div><span>Previous Balance</span><b>${money(previous)}</b></div><div><span>Paid Today</span><b>${money(paid)}</b></div><div class="grand"><span>Outstanding</span><b>${money(outstanding)}</b></div></div><div class="invoice-modal-actions"><button class="primary" onclick="printInvoice(${db.sales.indexOf(first)});closeInvoiceDetails()">🖨️ Print Invoice</button>${active.length?`<button class="danger" onclick="cancelSale(${db.sales.indexOf(first)});closeInvoiceDetails()">Cancel Invoice</button>`:''}<button class="secondary" onclick="closeInvoiceDetails()">Close</button></div></div>`;document.body.appendChild(modal)
}

