function cancelPurchase(billNo){
 if(!requirePerm('purchases.cancel'))return;
 const items=db.purchases.filter(x=>(x.billNo||x.id)===billNo&&x.status!=='Cancelled'); if(!items.length)return alert('Purchase bill not found or already cancelled.');
 if(!confirm('Cancel purchase '+billNo+'? Stock and cash effects will be reversed.'))return;
 for(const x of items){const p=db.products.find(p=>p.name===x.product);if(!p)return alert('Product not found: '+x.product);if(Number(p.qty)<Number(x.qty))return alert(x.product+': cannot cancel because current stock is lower than purchased quantity.');}
 const paid=items.reduce((a,x)=>a+Number(x.paidNow||0),0), accountId=items[0].accountId, account=paid>0?db.accounts.find(a=>a.id===accountId):null;
 if(paid>0&&!account)return alert('Original payment account not found.');
 if(paid>0&&Number(account.balance)<0)return alert('Invalid payment account balance.');
 const payment=items[0].payment||'Credit';
 for(const x of items){const p=db.products.find(p=>p.name===x.product);p.qty=Number(p.qty)-Number(x.qty);p.availableQty=p.qty;x.status='Cancelled';x.cancelledAt=new Date().toISOString();}
 if(paid>0)account.balance=Number(account.balance)+paid;
 if(payment==='Credit'&&paid>0){db.supplierPayments=db.supplierPayments.filter(p=>p.sourceBill!==billNo);}
 db.syncQueue.push({type:'purchase_cancel',billNo,items:items.map(x=>({id:x.id,qty:x.qty})),time:Date.now()});logAction('Purchase cancelled',billNo+' · '+money(items.reduce((a,x)=>a+Number(x.total||0),0)));save();closeDocumentDetails();page('purchases');
}
function cancelSale(i){
 if(!requirePerm('sales.cancel'))return;
 const first=db.sales[i]; if(!first)return;
 const invoice=first.invoice,items=db.sales.filter(x=>x.invoice===invoice&&x.status!=='Cancelled'); if(!items.length)return alert('Invoice is already cancelled.');
 if(!confirm('Cancel invoice '+invoice+'? Stock and cash effects will be reversed.'))return;
 for(const x of items){const p=db.products.find(p=>p.name===x.product);if(!p)return alert('Product not found: '+x.product);}
 const cashPaid=items.filter(x=>x.payment==='Cash').reduce((a,x)=>a+Number(x.total||0),0)+items.filter(x=>x.payment!=='Cash').reduce((a,x)=>a+Number(x.paidNow||0),0);
 const accountIds=[...new Set(items.map(x=>x.accountId).filter(Boolean))];
 for(const id of accountIds){const amount=items.filter(x=>x.accountId===id).reduce((a,x)=>a+(x.payment==='Cash'?Number(x.total||0):Number(x.paidNow||0)),0);const acc=db.accounts.find(a=>a.id===id);if(amount&&!acc)return alert('Payment account not found for invoice.');if(amount&&Number(acc.balance)<amount)return alert('Cannot cancel: '+acc.name+' balance is lower than the received amount.');}
 items.forEach(x=>{const p=db.products.find(p=>p.name===x.product);p.qty=Number(p.qty)+Number(x.qty);p.availableQty=p.qty;x.status='Cancelled';x.cancelledAt=new Date().toISOString();});
 for(const id of accountIds){const amount=items.filter(x=>x.accountId===id).reduce((a,x)=>a+(x.payment==='Cash'?Number(x.total||0):Number(x.paidNow||0)),0);if(amount){const acc=db.accounts.find(a=>a.id===id);acc.balance=Number(acc.balance)-amount;}}
 db.syncQueue.push({type:'sale_cancel',invoice,items:items.map(x=>({id:x.id,qty:x.qty})),time:Date.now()});logAction('Invoice cancelled',invoice+' · '+money(items.reduce((a,x)=>a+Number(x.total||0),0)));save();closeInvoiceDetails();page('sales');
}
