function cancelReturn(billNo,type){
 if(type==='Customer Return'&&!requirePerm('returns.customerCancel'))return;
 if(type==='Supplier Return'&&!requirePerm('returns.supplierCancel'))return;
 const arr=type==='Customer Return'?db.customerReturns:db.supplierReturns;const items=arr.filter(x=>(x.billNo||x.id)===billNo&&x.status!=='Cancelled');if(!items.length)return alert('Return bill not found or already cancelled.');if(!confirm('Cancel '+type+' '+billNo+'? Stock and cash effects will be reversed.'))return;
 const isCustomer=type==='Customer Return';
 for(const x of items){const p=db.products.find(p=>p.name===x.product);if(!p)return alert('Product not found: '+x.product);}
 for(const x of items){const p=db.products.find(p=>p.name===x.product);if(isCustomer){if(Number(p.qty)<Number(x.qty))return alert(x.product+': cannot cancel because current stock is lower than returned quantity.');p.qty-=Number(x.qty);p.availableQty=p.qty;}else{p.qty+=Number(x.qty);p.availableQty=p.qty;}x.status='Cancelled';x.cancelledAt=new Date().toISOString();}
 const cashTotal=items.filter(x=>x.method==='Cash Refund').reduce((a,x)=>a+Number(x.total||0),0);if(cashTotal){const acc=db.accounts.find(a=>a.id===items[0].accountId);if(!acc)return alert('Original refund account not found.');if(isCustomer)acc.balance+=cashTotal;else{if(Number(acc.balance)<cashTotal)return alert('Cannot cancel: '+acc.name+' balance is lower than the supplier refund.');acc.balance-=cashTotal;}}
 db.syncQueue.push({type:'return_cancel',billNo,returnType:type,time:Date.now()});logAction(type+' cancelled',billNo);save();closeDocumentDetails();page('returns');
}
function printInvoice(i){const x=db.sales[i];if(!x)return;const invoice=x.invoice,items=db.sales.filter(s=>s.invoice===invoice),active=items.filter(s=>s.status!=='Cancelled'),invoiceTotal=active.reduce((a,s)=>a+Number(s.total||0),0),discount=active.reduce((a,s)=>a+Number(s.discount||0),0),subtotal=invoiceTotal+discount,biz=db.settings.business||'RUHI MOBILE',rs=db.settings.receipt||{};const receiptMeta=[rs.showAddress!==false&&rs.address?rs.address:'',rs.showPhone!==false&&rs.phone?'Tel: '+rs.phone:'',rs.showTagline!==false&&rs.tagline?rs.tagline:''].filter(Boolean).join('<br>');let previousBalance=0,todayTotal=invoiceTotal,paidToday=Math.min(invoiceTotal,Number(x.paidNow||((x.payment==='Cash')?invoiceTotal:0))),outstanding=0;if(x.customer&&x.customer!=='Cash Customer'){const customer=x.customer,invoiceDate=new Date(x.date),opening=Number((db.customers.find(c=>c.name===customer)||{}).openingBalance||0),priorSales=db.sales.filter(s=>s.status!=='Cancelled'&&s.customer===customer&&s.invoice!==invoice&&new Date(s.date)<invoiceDate).reduce((a,s)=>a+Number(s.total||0),0),priorPayments=db.customerPayments.filter(p=>p.customer===customer&&new Date(p.date)<invoiceDate).reduce((a,p)=>a+Number(p.amount||0),0),priorReturns=db.customerReturns.filter(r=>r.status!=='Cancelled'&&r.customer===customer&&new Date(r.date)<invoiceDate).reduce((a,r)=>a+Number(r.total||0),0);previousBalance=Math.max(0,opening+priorSales-priorPayments-priorReturns);outstanding=Math.max(0,previousBalance+invoiceTotal-paidToday)}else{outstanding=Math.max(0,invoiceTotal-paidToday)}const rows=active.map(s=>`<tr><td>${s.product}</td><td class="num">${s.qty}</td><td class="num">${money(s.unitPrice)}</td><td class="num">${money(s.discount)}</td><td class="num">${money(s.total)}</td></tr>`).join('');const w=window.open('','_blank','width=800,height=1000');if(!w)return alert('Please allow pop-ups to print the invoice.');w.document.write(`<!doctype html><html><head><title>${invoice||'Invoice'}</title><style>body{font-family:Arial,sans-serif;padding:30px;color:#111}.top{display:flex;justify-content:space-between}h1{margin:0 0 4px}.muted{color:#666}.line{border-top:1px solid #ccc;margin:20px 0}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}td.num,th.num{text-align:right}.summary{margin-left:auto;width:360px;margin-top:20px}.summary div{display:flex;justify-content:space-between;padding:7px 0}.summary .grand{font-size:18px;font-weight:bold;border-top:2px solid #111;border-bottom:2px solid #111}.summary .outstanding{font-size:20px;font-weight:bold;padding-top:12px}.actions{text-align:center;margin-top:30px}@media print{.actions{display:none}body{padding:0}}</style></head><body><div class="top"><div><h1>${biz}</h1><div class="muted">${receiptMeta}${receiptMeta?'<br>':''}${active.length?'':'CANCELLED '}Invoice</div></div><div><b>${invoice||''}</b><br>${fmtDate(x.date)}</div></div><div class="line"></div><p><b>Customer:</b> ${x.customer||'Cash Customer'}</p><table><tr><th>Item</th><th class="num">Qty</th><th class="num">Unit Price</th><th class="num">Discount</th><th class="num">Total</th></tr>${rows}</table><div class="summary"><div><span>Sub Total</span><b>${money(subtotal)}</b></div><div><span>Discount</span><b>${money(discount)}</b></div><div class="grand"><span>Total</span><b>${money(invoiceTotal)}</b></div><div><span>Previous Balance</span><b>${money(previousBalance)}</b></div><div><span>Paid</span><b>${money(paidToday)}</b></div><div class="outstanding"><span>Outstanding</span><b>${money(outstanding)}</b></div></div><p><b>Payment:</b> ${x.payment||'Cash'}${x.payment==='Cash'?' — '+accountName(x.accountId):''}</p><div class="actions"><button onclick="window.print()">Print Invoice</button></div><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);w.document.close()}
