function addCustomer(e){e.preventDefault();if(!requirePerm('customers.create'))return;const opening=Number(document.getElementById('copen')?.value||0);if(opening<0)return alert('Opening balance cannot be negative.');const c={id:'C-'+Date.now(),name:document.getElementById('cname').value.trim(),idNumber:document.getElementById('cid').value.trim(),area:document.getElementById('carea').value.trim(),category:document.getElementById('ccategory').value.trim(),mapLocation:document.getElementById('cmap').value.trim(),email:document.getElementById('cemail').value.trim(),phone:document.getElementById('cphone').value.trim(),address:document.getElementById('caddress').value.trim(),description:document.getElementById('cdescription').value.trim(),customerType:document.getElementById('ccustomerType')?.value||'Retail',openingBalance:opening,balanceType:document.querySelector('input[name=cbaltype]:checked')?.value||'Receivable'};db.customers.push(c);db.syncQueue.push({type:'customer',customer:c,time:Date.now()});save();page('customers')}
function addRepair(e){e.preventDefault();if(!requirePerm('repairs.create'))return;const now=new Date().toISOString(),id='REP-'+Date.now()+'-'+Math.random().toString(16).slice(2,6).toUpperCase(),jobNo='RJ-'+new Date().toISOString().slice(0,10).replace(/-/g,'')+'-'+String(db.repairs.length+1).padStart(4,'0'),job={id,jobNo,name:document.getElementById('rname').value.trim(),phone:document.getElementById('rphone').value.trim(),problem:document.getElementById('rproblem').value.trim(),charge:Number(document.getElementById('rcharge').value||0),notes:document.getElementById('rnotes').value.trim(),status:document.getElementById('rstatus').value,technician:document.getElementById('rtechnician').value.trim(),date:now,createdBy:currentUser()?.name||currentUser()?.username||'Unknown',createdByUsername:currentUser()?.username||'',updatedBy:currentUser()?.name||'Unknown',updatedAt:now};db.repairs.push(job);db.syncQueue.push({type:'repair',repair:job,time:Date.now()});logAction('Repair job created',jobNo+' · '+job.name);save();page('repairs')}
function openRepairDetails(id){const x=db.repairs.find(r=>r.id===id);if(!x)return;const box=document.createElement('div');box.className='modal-backdrop';box.innerHTML=`<div class="modal-card"><button class="secondary" style="float:right" onclick="this.closest('.modal-backdrop').remove()">Close ✕</button><h2>Repair Job ${x.jobNo||x.id}</h2><p><b>Customer:</b> ${escapeHtml(x.name)} &nbsp; <b>Phone / Model:</b> ${escapeHtml(x.phone)}</p><p><b>Problem:</b> ${escapeHtml(x.problem)}</p><p><b>Notes:</b><br>${escapeHtml(x.notes||'—').replace(/\n/g,'<br>')}</p><p><b>Status:</b> ${escapeHtml(x.status||'Received')} &nbsp; <b>Technician:</b> ${escapeHtml(x.technician||'—')}</p><p><b>Estimated charge:</b> ${money(x.charge)}</p><p><b>Created:</b> ${fmtDate(x.date)} by ${escapeHtml(x.createdBy||'—')}</p><p><b>Last updated:</b> ${fmtDate(x.updatedAt||x.date)} by ${escapeHtml(x.updatedBy||x.createdBy||'—')}</p><label>Update status</label><select id="repairStatusEdit">${['Received','Diagnosing','Waiting for Parts','In Repair','Completed','Done','Collected','Closed','Cancelled'].map(s=>`<option ${s===(x.status||'Received')?'selected':''}>${s}</option>`).join('')}</select><label>Update notes</label><textarea id="repairNotesEdit">${escapeHtml(x.notes||'')}</textarea><button class="primary" onclick="updateRepair('${x.id}')">Save Update</button><button class="secondary" onclick="window.print()">Print</button></div>`;document.body.appendChild(box)}
function updateRepair(id){if(!requirePerm('repairs.edit'))return;const x=db.repairs.find(r=>r.id===id);if(!x)return;x.status=document.getElementById('repairStatusEdit').value;x.notes=document.getElementById('repairNotesEdit').value;x.updatedAt=new Date().toISOString();x.updatedBy=currentUser()?.name||'Unknown';logAction('Repair job updated',(x.jobNo||x.id)+' status '+x.status);db.syncQueue.push({type:'repair_update',repair:x,time:Date.now()});save();page('repairs')}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function exportRepairs(){const rows=[['Job No','Date','Customer','Phone/Model','Problem','Notes','Status','Technician','Charge','Created By'],...db.repairs.map(x=>[x.jobNo||x.id,x.date,x.name,x.phone,x.problem,x.notes,x.status,x.technician,x.charge,x.createdBy])];downloadCSV('ruhi-repair-jobs.csv',rows)}
function addExpense(e){e.preventDefault();if(!requirePerm('expenses.create'))return;const amount=Number(eamt.value),accountId=document.getElementById('eaccount')?.value||'A-inhand',a=db.accounts.find(x=>x.id===accountId);if(!a)return alert('Select an account.');if(!Number.isFinite(amount)||amount<=0)return alert('Enter a valid amount.');if(Number(a.balance)<amount)return alert('Not enough money in '+a.name+'. Available: '+money(a.balance));a.balance-=amount;db.expenses.push({id:'EXP-'+Date.now(),desc:edesc.value,amount,accountId,date:new Date().toISOString(),createdBy:currentUser()?.name||'Unknown',createdByUsername:currentUser()?.username||''});db.syncQueue.push({type:'expense',amount,accountId,time:Date.now()});save();page('expenses')}
let activeServerUser=null;
function apiFetch(path,options={}){const token=sessionStorage.getItem('ruhi_session_token');const headers={'Content-Type':'application/json',...(options.headers||{})};if(token)headers.Authorization='Bearer '+token;return fetch(path,{...options,headers});}
async function syncServerUsers(){try{const r=await apiFetch('/api/users');if(!r.ok)return false;const j=await r.json();db.users=(j.users||[]).map(u=>({...u,password:undefined}));save();return true}catch(e){return false}}
function currentUser(){return activeServerUser}
function showLogin(){
  refreshNav();
  const title=document.getElementById('pageTitle'); if(title) title.textContent='Login';
  const c=document.getElementById('content'); if(!c)return;
  const users=db.users||[];
  c.innerHTML=`<div class="auth-wrap"><div class="panel auth-card">
    <div class="brand">RUHI MOBILE</div><p class="muted">Business Manager</p><h2>🔐 User Login</h2>
    <div id="loginError"></div>
    <form onsubmit="loginUser(event)">
      <div><label>Username</label><input id="loginUsername" autocomplete="username" required placeholder="Enter username"></div>
      <div><label>Password</label><input id="loginPassword" type="password" autocomplete="current-password" required placeholder="Enter password"></div>
      <div class="auth-actions"><button class="primary">Login</button><span class="muted">${users.length} user${users.length===1?'':'s'} configured</span></div>
    </form>
    <br><p class="muted">Authentication is handled by the Ruhi Mobile server. Default first-run administrator: <b>admin</b> / <b>admin</b>.</p>
  </div></div>`;
  setTimeout(()=>document.getElementById('loginUsername')?.focus(),50);
}
async function loginUser(e){
  e.preventDefault();
  const username=document.getElementById('loginUsername').value.trim().toLowerCase();
  const password=document.getElementById('loginPassword').value;
  try{
    const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username,password})});
    const j=await r.json();
    if(!r.ok){const box=document.getElementById('loginError');if(box)box.innerHTML='<div class="auth-error">'+(j.error||'Login failed')+'</div>';return;}
    sessionStorage.setItem('ruhi_session_token',j.token); sessionStorage.setItem('ruhi_session_user',j.user.id); activeServerUser=j.user;
    await syncServerUsers(); await loadCloudData(); save(); refreshNav(); document.getElementById('pageTitle').textContent='Dashboard'; page('dashboard');
  }catch(err){const box=document.getElementById('loginError');if(box)box.innerHTML='<div class="auth-error">Server unavailable. Start Ruhi Mobile with: npm start</div>';}
}
async function logoutUser(){
  const u=currentUser(); if(!u)return showLogin();
  if(!confirm('Logout '+u.name+'?'))return;
  try{await apiFetch('/api/logout',{method:'POST'});}catch(e){}
  sessionStorage.removeItem('ruhi_session_token');sessionStorage.removeItem('ruhi_session_user');activeServerUser=null; save(); refreshNav(); showLogin();
}
async function restoreServerSession(){
  const token=sessionStorage.getItem('ruhi_session_token'); if(!token){activeServerUser=null;refreshNav();showLogin();return;}
  try{const r=await apiFetch('/api/me');if(!r.ok)throw new Error('expired');const j=await r.json();activeServerUser=j.user;await syncServerUsers();await loadCloudData();refreshNav();page('dashboard');}catch(e){sessionStorage.removeItem('ruhi_session_token');sessionStorage.removeItem('ruhi_session_user');activeServerUser=null;refreshNav();showLogin();}
}
function canAccess(p){return !!(currentUser() && hasPerm(SECTION_PERM[p]||p));}
function refreshNav(){const logged=!!currentUser();document.body.classList.toggle('logged-out',!logged);document.querySelectorAll('.nav').forEach(b=>{const ok=logged&&canAccess(b.dataset.page);b.style.display=ok?'':'none';b.disabled=!ok});const sync=document.getElementById('syncBtn');if(sync)sync.style.display=logged?'':'none';const btn=document.getElementById('authBtn');if(btn){btn.textContent=logged?'Logout':'Login';btn.onclick=logged?logoutUser:showLogin;btn.style.display=logged?'':'none';}const title=document.getElementById('pageTitle');if(title&&!logged)title.textContent='Login';}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{if(canAccess(b.dataset.page))page(b.dataset.page);else alert('You do not have permission for this section.');});
window.addEventListener('online',updateStatus);window.addEventListener('offline',updateStatus);updateStatus();refreshNav();restoreServerSession();

function accountName(id){return db.accounts.find(a=>a.id===id)?.name||'—'}
function buildTransactions(){const tx=[];db.sales.forEach(x=>{if(x.status!=='Cancelled'&&x.payment==='Cash')tx.push({date:x.date,type:'Sale',desc:(x.invoice||'Sale')+' — '+x.product,account:accountName(x.accountId),in:Number(x.total||0),out:0})});db.purchases.forEach(x=>{if(x.payment==='Cash')tx.push({date:x.date,type:'Purchase',desc:x.supplier+' — '+x.product,account:accountName(x.accountId),in:0,out:Number(x.total||0)})});db.customerPayments.forEach(x=>tx.push({date:x.date,type:'Customer Payment',desc:'Received from '+x.customer,account:accountName(x.accountId),in:Number(x.amount||0),out:0}));db.customerReturns.forEach(x=>{if(x.status!=='Cancelled')tx.push({date:x.date,type:'Customer Return',desc:'Return from '+x.customer+' — '+x.product,account:accountName(x.accountId),in:0,out:x.method==='Cash Refund'?Number(x.total||0):0});}) ;db.supplierReturns.forEach(x=>{if(x.status!=='Cancelled')tx.push({date:x.date,type:'Supplier Return',desc:'Return to '+x.supplier+' — '+x.product,account:accountName(x.accountId),in:x.method==='Cash Refund'?Number(x.total||0):0,out:0});}) ;db.supplierPayments.forEach(x=>tx.push({date:x.date,type:'Supplier Payment',desc:'Paid to '+x.supplier,account:accountName(x.accountId),in:0,out:Number(x.amount||0)}));db.expenses.forEach(x=>tx.push({date:x.date,type:'Expense',desc:x.desc,account:accountName(x.accountId),in:0,out:Number(x.amount||0)}));db.accountAdjustments.forEach(x=>{tx.push({date:x.date,type:'Account Adjustment',desc:x.accountName,account:x.accountName,in:Number(x.amount)>0?Number(x.amount):0,out:Number(x.amount)<0?Math.abs(Number(x.amount)):0})});db.transfers.forEach(x=>{tx.push({date:x.date,type:'Transfer Out',desc:(x.note||'Transfer')+' → '+x.toName,account:x.fromName,in:0,out:Number(x.amount||0)});tx.push({date:x.date,type:'Transfer In',desc:(x.note||'Transfer')+' ← '+x.fromName,account:x.toName,in:Number(x.amount||0),out:0})});return tx}
function accountBook(id){const a=db.accounts.find(x=>x.id===id);if(!a)return;const tx=buildTransactions().filter(x=>x.account===a.name).sort((x,y)=>new Date(x.date)-new Date(y.date));let bal=0,lines='';tx.forEach(x=>{bal+=Number(x.in||0)-Number(x.out||0);lines+=`${new Date(x.date).toLocaleString()} | ${x.type} | ${x.desc} | IN ${money(x.in)} | OUT ${money(x.out)} | Balance ${money(bal)}\n`});alert(a.name+' Book\n\n'+lines+'\nCurrent Account Balance: '+money(a.balance))}
function addSupplier(e){e.preventDefault();if(!requirePerm('suppliers.create'))return;const opening=Number(document.getElementById('vopen')?.value||0);if(opening<0)return alert('Opening balance cannot be negative.');const v={id:'V-'+Date.now(),name:document.getElementById('vname').value.trim(),idNumber:document.getElementById('vid').value.trim(),area:document.getElementById('varea').value.trim(),category:document.getElementById('vcategory').value.trim(),mapLocation:document.getElementById('vmap').value.trim(),email:document.getElementById('vemail').value.trim(),phone:document.getElementById('vphone').value.trim(),address:document.getElementById('vaddress').value.trim(),description:document.getElementById('vdescription').value.trim(),openingBalance:opening,balanceType:document.querySelector('input[name=vbaltype]:checked')?.value||'Payable'};db.suppliers.push(v);db.syncQueue.push({type:'supplier',supplier:v,time:Date.now()});save();page('suppliers')}
function saveAdvancedSettings(){if(!requirePerm('settings.edit'))return;db.settings.confirmCancel=document.getElementById('settingConfirmCancel').checked;db.settings.auditEnabled=document.getElementById('settingAudit').checked;db.settings.compactMode=document.getElementById('settingCompact').checked;save();alert('System controls saved.');page('settings')}
function downloadCSV(filename,rows){const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function saveSettings(e){e.preventDefault();if(!requirePerm('settings.edit'))return;db.settings={...db.settings,business:bname.value.trim()||'RUHI MOBILE',currency:bcurrency.value.trim()||'LKR',apiUrl:bapi.value.trim(),receipt:db.settings.receipt||{address:'Sri Lanka',phone:'0720244445',tagline:'Enjoy your smart life with us.',showAddress:true,showPhone:true,showTagline:true}};save();alert('Settings saved');page('dashboard')}
function addCashAccount(e){e.preventDefault();if(!requirePerm('accounts.create'))return;const name=document.getElementById('newAccountName').value.trim();const balance=Number(document.getElementById('newAccountBalance').value||0);if(!name)return alert('Enter account name.');if(!Number.isFinite(balance)||balance<0)return alert('Invalid opening balance.');if(db.accounts.some(a=>a.name.toLowerCase()===name.toLowerCase()))return alert('An account with this name already exists.');const a={id:'A-'+Date.now(),name,balance};db.accounts.push(a);db.syncQueue.push({type:'account_add',account:a,time:Date.now()});save();page('accounts')}
function editCashAccount(i){const a=db.accounts[i];if(!requirePerm('accounts.edit'))return;if(!a)return;const name=prompt('Account name:',a.name);if(name===null)return;const n=name.trim();if(!n)return alert('Account name is required.');if(db.accounts.some((x,j)=>j!==i&&x.name.toLowerCase()===n.toLowerCase()))return alert('Another account already has this name.');a.name=n;db.syncQueue.push({type:'account_edit',account:{...a},time:Date.now()});save();page('accounts')}
function deleteCashAccount(i){const a=db.accounts[i];if(!requirePerm('accounts.delete'))return;if(!a)return;if(db.accounts.length<=1)return alert('Keep at least one cash account.');const used=db.sales.some(x=>x.accountId===a.id)||db.purchases.some(x=>x.accountId===a.id)||db.customerPayments.some(x=>x.accountId===a.id)||db.supplierPayments.some(x=>x.accountId===a.id)||db.expenses.some(x=>x.accountId===a.id)||db.customerReturns.some(x=>x.accountId===a.id)||db.supplierReturns.some(x=>x.accountId===a.id)||db.transfers.some(x=>x.from===a.id||x.to===a.id);if(used)return alert('This account has transaction history. Edit or keep it instead of deleting.');if(Number(a.balance)!==0)return alert('Account balance must be LKR 0.00 before deleting.');if(confirm('Delete '+a.name+'?')){db.accounts.splice(i,1);db.syncQueue.push({type:'account_delete',accountId:a.id,time:Date.now()});save();page('accounts')}}
function saveReceiptSettings(e){e.preventDefault();db.settings.receipt={address:document.getElementById('raddress').value.trim(),phone:document.getElementById('rphone').value.trim(),tagline:document.getElementById('rtagline').value.trim(),showAddress:document.getElementById('rshowAddress').checked,showPhone:document.getElementById('rshowPhone').checked,showTagline:document.getElementById('rshowTagline').checked};save();alert('Print settings saved');page('settings')}
function printReceiptPreview(){const r=db.settings.receipt||{};const lines=[r.showAddress!==false&&r.address?r.address:'',r.showPhone!==false&&r.phone?'Tel: '+r.phone:'',r.showTagline!==false&&r.tagline?r.tagline:''].filter(Boolean).join('<br>');const w=window.open('','_blank','width=500,height=700');if(!w)return alert('Please allow pop-ups.');w.document.write('<!doctype html><html><head><title>Receipt Preview</title><style>body{font-family:Arial;padding:30px;text-align:center}h1{margin-bottom:6px}.muted{color:#666}</style></head><body><h1>'+String(db.settings.business||'RUHI MOBILE').replace(/</g,'&lt;')+'</h1><div>'+lines+'</div><hr><p class="muted">Receipt preview</p><button onclick="window.print()">Print</button></body></html>');w.document.close()}
function exportData(){if(!requirePerm('backup.export'))return;const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ruhi-mobile-backup.json';a.click()}
function importData(){if(!requirePerm('backup.import'))return;const i=document.createElement('input');i.type='file';i.accept='.json';i.onchange=()=>{const r=new FileReader();r.onload=()=>{try{db=JSON.parse(r.result);save();location.reload()}catch(e){alert('Invalid backup')}};r.readAsText(i.files[0])};i.click()}

async function syncNow(){if(!requirePerm('backup.sync'))return;
  if(!navigator.onLine){db.syncMeta.status='Offline — queued';save();page('backup');return}
  const url=db.settings.apiUrl;
  if(!url){db.syncMeta.status='No cloud API configured';save();page('backup');return}
  try{
    const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({business:db.settings.business,data:db.syncQueue})});
    if(!r.ok) throw new Error('HTTP '+r.status);
    db.syncQueue=[]; db.syncMeta.lastSync=new Date().toISOString(); db.syncMeta.status='Synced'; save(); page('backup');
  }catch(e){db.syncMeta.status='Sync failed — kept offline queue';save();page('backup')}
}
function permissionGroupsHtml(prefix='perm'){return Object.entries(PERMISSION_GROUPS).map(([group,items])=>`<div class="perm-group"><div class="perm-group-head"><b>${group}</b><span><button type="button" class="mini" onclick="setPermissionGroup('${group}',true)">All</button><button type="button" class="mini" onclick="setPermissionGroup('${group}',false)">None</button></span></div>${items.map(([k,label])=>`<label class="check"><input type="checkbox" class="uperm" data-group="${group}" value="${k}"> ${label}</label>`).join('')}</div>`).join('')}
function setPermissionGroup(group,value){document.querySelectorAll('.uperm[data-group="'+CSS.escape(group)+'"]').forEach(x=>{x.checked=value;x.disabled=document.getElementById('urole')?.value==='Administrator';});}
function syncPermissionBoxes(){const role=document.getElementById('urole')?.value;const boxes=[...document.querySelectorAll('.uperm')];const perms=role==='Custom'?Object.fromEntries(boxes.map(x=>[x.value,x.checked])):ROLE_PERMS[role]||ROLE_PERMS.Cashier;boxes.forEach(x=>{x.checked=!!perms[x.value]||role==='Administrator';x.disabled=role==='Administrator';});}
function hasPerm(k){const u=currentUser();return !!(u&&(u.role==='Administrator'||u.permissions?.all||u.permissions?.[k]));}
function requirePerm(k){if(!hasPerm(k)){alert('Permission denied: '+k);return false;}return true;}
function manageUserPermissions(i){
 const u=db.users[i]; if(!u||!requirePerm('users.permissions'))return;
 const modal=document.createElement('div');modal.className='modal-backdrop';modal.id='permissionModal';
 modal.innerHTML=`<div class="modal-card"><div class="modal-head"><h3>🔐 Permissions — ${u.name}</h3><button class="danger" onclick="document.getElementById('permissionModal')?.remove()">×</button></div><p class="muted">Enable only what this user is allowed to do. Changes take effect on the next navigation/action check.</p><div class="perm-grid advanced-perms">${Object.entries(PERMISSION_GROUPS).map(([group,items])=>`<div class="perm-group"><div class="perm-group-head"><b>${group}</b><span><button type="button" class="mini" onclick="modalGroup('${group}',true)">All</button><button type="button" class="mini" onclick="modalGroup('${group}',false)">None</button></span></div>${items.map(([k,label])=>`<label class="check"><input type="checkbox" class="modalperm" data-group="${group}" value="${k}" ${u.permissions?.all||u.permissions?.[k]?'checked':''}> ${label}</label>`).join('')}</div>`).join('')}</div><div class="modal-actions"><button class="secondary" onclick="document.getElementById('permissionModal')?.remove()">Cancel</button><button class="primary" onclick="saveManagedPermissions('${u.id}')">💾 Save Permissions</button></div></div>`;
 document.body.appendChild(modal);
}
function modalGroup(group,value){document.querySelectorAll('.modalperm[data-group="'+CSS.escape(group)+'"]').forEach(x=>x.checked=value)}
async function saveManagedPermissions(id){if(!requirePerm('users.permissions'))return;const perms=Object.fromEntries([...document.querySelectorAll('.modalperm')].map(x=>[x.value,x.checked]));try{const r=await apiFetch('/api/users/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify({permissions:perms})});const j=await r.json();if(!r.ok)return alert(j.error||'Could not save permissions.');await syncServerUsers();if(currentUser()?.id===id)activeServerUser=j.user;document.getElementById('permissionModal')?.remove();refreshNav();page('users');}catch(e){alert('Server unavailable.');}}
async function addUser(e){e.preventDefault();if(!requirePerm('users.create'))return;const name=document.getElementById('uname').value.trim(),username=document.getElementById('uusername').value.trim().toLowerCase(),password=document.getElementById('upassword').value,role=document.getElementById('urole').value;const perms=normalizePermissions(role==='Custom'?Object.fromEntries([...document.querySelectorAll('.uperm')].map(x=>[x.value,x.checked])):JSON.parse(JSON.stringify(ROLE_PERMS[role]||ROLE_PERMS.Cashier)));if(!name||!username||!password)return alert('Fill name, username and password.');try{const r=await apiFetch('/api/users',{method:'POST',body:JSON.stringify({name,username,password,role,permissions:perms})});const j=await r.json();if(!r.ok)return alert(j.error||'Could not create user.');await syncServerUsers();page('users')}catch(err){alert('Server unavailable.');}}
function switchUser(i){const u=db.users[i];if(!u)return;if(currentUser()?.role!=='Administrator')return alert('Only an Administrator can switch users here. Please logout and login with the required account.');const pass=prompt('Password for '+u.username+':');if(pass===null)return;if(pass!==u.password)return alert('Incorrect password.');const old=currentUser();if(old&&old.id!==u.id)logAction('User switch',old.name+' → '+u.name);sessionStorage.setItem('ruhi_session_user',u.id);logAction('User login',u.name);save();refreshNav();page('dashboard')}
async function editUser(i){if(!requirePerm('users.edit'))return;const u=db.users[i];if(!u)return;const name=prompt('Name:',u.name);if(name===null)return;const role=prompt('Role (Administrator / Cashier / Stock Manager / Repair Staff / Custom):',u.role);if(role===null)return;const pass=prompt('New password (leave blank to keep current):','');let permissions=u.permissions||{};if(role.trim()==='Custom'){const selected=prompt('Enter allowed sections comma-separated:\n'+PERM_KEYS.join(', '),Object.keys(permissions).filter(k=>permissions[k]).join(', '));if(selected===null)return;const set=new Set(selected.split(',').map(x=>x.trim()));permissions=Object.fromEntries(PERM_KEYS.map(k=>[k,set.has(k)]));}else permissions=ROLE_PERMS[role.trim()]||ROLE_PERMS.Cashier;permissions=normalizePermissions(permissions);const body={name:name.trim()||u.name,role:role.trim()||u.role,permissions};if(pass)body.password=pass;try{const r=await apiFetch('/api/users/'+encodeURIComponent(u.id),{method:'PUT',body:JSON.stringify(body)});const j=await r.json();if(!r.ok)return alert(j.error||'Could not edit user.');await syncServerUsers();if(currentUser()?.id===u.id){activeServerUser=j.user;}refreshNav();page('users')}catch(e){alert('Server unavailable.')}}
async function deleteUser(i){if(!requirePerm('users.delete'))return;const u=db.users[i];if(!u||u.id==='U-admin')return;if(u.id===currentUser()?.id)return alert('Logout this user before deleting the account.');if(confirm('Delete '+u.name+'?')){try{const r=await apiFetch('/api/users/'+encodeURIComponent(u.id),{method:'DELETE'});const j=await r.json();if(!r.ok)return alert(j.error||'Could not delete user.');await syncServerUsers();page('users')}catch(e){alert('Server unavailable.')}}}

function toggleReturnAccount(methodId,wrapId){const m=document.getElementById(methodId),w=document.getElementById(wrapId);if(w&&m)w.style.display=m.value==='Cash Refund'?'block':'none'}
function addCustomerReturn(e){e.preventDefault();if(!requirePerm('returns.customerCreate'))return;const customer=document.getElementById('rccust').value,productName=document.getElementById('rcprod').value,qty=Number(document.getElementById('rcqty').value),price=Number(document.getElementById('rcprice').value),p=db.products.find(x=>x.name===productName),current=(p&&qty>0&&price>=0)?[{product:p.name,qty,price,total:qty*price}]:[],lines=[...customerReturnDraft,...current],method=document.getElementById('rcmethod').value,accountId=document.getElementById('rcaccount')?.value;if(!customer||!lines.length)return alert('Select customer and add at least one item.');const total=lines.reduce((a,x)=>a+x.total,0),account=method==='Cash Refund'?db.accounts.find(x=>x.id===accountId):null;if(method==='Cash Refund'&&(!account||Number(account.balance)<total))return alert(account?'Not enough money in '+account.name+'.':'Select refund account.');const billNo='CRB-'+String(Date.now()),now=new Date().toISOString();for(const l of lines){const pp=db.products.find(x=>x.name===l.product);if(!pp)return alert('Product not found: '+l.product);pp.qty=Number(pp.qty)+l.qty;const r={id:'CR-'+Date.now()+'-'+Math.random().toString(16).slice(2),billNo,customer,product:pp.name,qty:l.qty,price:l.price,total:l.total,method,accountId,status:'Active',date:now,remarks:document.getElementById('customerReturnRemarks')?.value.trim()||'',createdBy:currentUser()?.name||'Unknown',createdByUsername:currentUser()?.username||''};db.customerReturns.push(r);db.syncQueue.push({type:'customer_return',return:r,time:Date.now()})}if(method==='Cash Refund')account.balance=Number(account.balance)-total;logAction('Customer return saved',billNo+' · '+customer+' · '+money(total));save();clearDrafts();alert('Customer return bill '+billNo+' saved with '+lines.length+' item(s).');page('returns')}
function addSupplierReturn(e){e.preventDefault();if(!requirePerm('returns.supplierCreate'))return;const supplier=document.getElementById('rsupplier').value,productName=document.getElementById('rsprod').value,qty=Number(document.getElementById('rsqty').value),price=Number(document.getElementById('rsprice').value),p=db.products.find(x=>x.name===productName),current=(p&&qty>0&&price>=0)?[{product:p.name,qty,price,total:qty*price}]:[],lines=[...supplierReturnDraft,...current],method=document.getElementById('rsmethod').value,accountId=document.getElementById('rsaccount').value;if(!supplier||!lines.length)return alert('Select supplier and add at least one item.');const total=lines.reduce((a,x)=>a+x.total,0),account=method==='Cash Refund'?db.accounts.find(x=>x.id===accountId):null;if(method==='Cash Refund'&&!account)return alert('Select refund account.');for(const l of lines){const pp=db.products.find(x=>x.name===l.product);if(!pp||Number(pp.qty)<l.qty)return alert(l.product+': Not enough stock.')}const billNo='SRB-'+String(Date.now()),now=new Date().toISOString();for(const l of lines){const pp=db.products.find(x=>x.name===l.product);pp.qty=Number(pp.qty)-l.qty;const r={id:'SR-'+Date.now()+'-'+Math.random().toString(16).slice(2),billNo,supplier,product:pp.name,qty:l.qty,price:l.price,total:l.total,method,accountId,status:'Active',date:now,remarks:document.getElementById('supplierReturnRemarks')?.value.trim()||'',createdBy:currentUser()?.name||'Unknown',createdByUsername:currentUser()?.username||''};db.supplierReturns.push(r);db.syncQueue.push({type:'supplier_return',return:r,time:Date.now()})}if(method==='Cash Refund')account.balance=Number(account.balance)+total;save();clearDrafts();alert('Supplier return bill '+billNo+' saved with '+lines.length+' item(s).');page('returns')}
function cancelCustomerReturn(i){if(!requirePerm('returns.customerCancel'))return;const r=db.customerReturns[i];if(!r||r.status==='Cancelled')return;if(!confirm('Cancel '+(r.billNo||'customer return')+'? Stock and cash effects will be reversed.'))return;const p=db.products.find(x=>x.name===r.product);if(p){if(Number(p.qty)<Number(r.qty))return alert('Cannot cancel: not enough current stock to reverse this return.');p.qty=Number(p.qty)-Number(r.qty);}if(r.method==='Cash Refund'&&r.accountId){const a=db.accounts.find(x=>x.id===r.accountId);if(a)a.balance+=Number(r.total||0);}r.status='Cancelled';r.cancelledAt=new Date().toISOString();db.syncQueue.push({type:'customer_return_cancel',return:{...r},time:Date.now()});save();page('returns')}
function cancelSupplierReturn(i){if(!requirePerm('returns.supplierCancel'))return;const r=db.supplierReturns[i];if(!r||r.status==='Cancelled')return;if(!confirm('Cancel '+(r.billNo||'supplier return')+'? Stock and cash effects will be reversed.'))return;const p=db.products.find(x=>x.name===r.product);if(p)p.qty=Number(p.qty)+Number(r.qty);if(r.method==='Cash Refund'&&r.accountId){const a=db.accounts.find(x=>x.id===r.accountId);if(a){if(Number(a.balance)<Number(r.total||0)){if(p)p.qty-=Number(r.qty);return alert('Cannot cancel: '+a.name+' does not have enough balance to reverse this refund.');}a.balance-=Number(r.total||0);}}r.status='Cancelled';r.cancelledAt=new Date().toISOString();db.syncQueue.push({type:'supplier_return_cancel',return:{...r},time:Date.now()});save();page('returns')}
function paySupplier(i){if(!requirePerm('suppliers.payment'))return;
 const s=db.suppliers[i]; if(!s)return;
 const credit=db.purchases.filter(a=>a.supplier===s.name&&a.payment==='Credit').reduce((a,x)=>a+Number(x.total),0);
 const paid=db.supplierPayments.filter(a=>a.supplier===s.name).reduce((a,x)=>a+Number(x.amount),0); const returns=db.supplierReturns.filter(a=>a.supplier===s.name&&a.method==='Credit Adjustment'&&a.status!=='Cancelled').reduce((a,x)=>a+Number(x.total),0); const balance=Math.max(0,Number(s.openingBalance||0)+credit-paid-returns);
 if(balance<=0){alert('No outstanding balance for '+s.name+'.');return}
 const amount=Number(prompt('Payment to '+s.name+'\nOutstanding: '+money(balance)+'\n\nEnter amount:',balance)); if(!Number.isFinite(amount)||amount<=0)return; if(amount>balance){alert('Payment cannot exceed outstanding balance.');return}
 const choice=Number(prompt('Pay from account:\n'+db.accounts.map((a,n)=>`${n+1}. ${a.name} (${money(a.balance)})`).join('\n')+'\n\nEnter account number:','1'))-1; const acc=db.accounts[choice]; if(!acc)return alert('Invalid account.'); if(Number(acc.balance)<amount)return alert('Not enough money in '+acc.name+'.'); acc.balance-=amount;
 db.supplierPayments.push({id:'SP-'+Date.now(),supplier:s.name,amount,accountId:acc.id,date:new Date().toISOString(),createdBy:currentUser()?.name||'Unknown',createdByUsername:currentUser()?.username||''}); db.syncQueue.push({type:'supplier_payment',supplier:s.name,amount,accountId:acc.id,time:Date.now()}); save(); page('suppliers');
}
function supplierStatement(i){const s=db.suppliers[i];if(!s)return;const events=[];const byBill={};db.purchases.filter(x=>x.supplier===s.name&&x.status!=="Cancelled").forEach(x=>{const no=x.billNo||x.id||x.bill||"PURCHASE";if(!byBill[no])byBill[no]={date:x.date,no,desc:x.payment==="Cash"?"Cash Purchase":"Credit Purchase",amount:0};byBill[no].amount+=Number(x.total||0)});Object.values(byBill).forEach(x=>events.push(x));db.supplierReturns.filter(x=>x.supplier===s.name&&x.status!=="Cancelled").forEach(x=>events.push({date:x.date,no:x.billNo||x.id||"RETURN",desc:x.method==="Cash Refund"?"Supplier Return (Cash)":"Supplier Return (Credit Adjustment)",amount:-Number(x.total||0)}));db.supplierPayments.filter(x=>x.supplier===s.name).forEach(x=>events.push({date:x.date,no:x.id||"PAYMENT",desc:"Payment to Supplier",amount:-Number(x.amount||0)}));events.sort((a,b)=>new Date(a.date)-new Date(b.date));let running=Number(s.openingBalance||0);const rows=events.map(x=>{running+=x.amount;return `<tr><td>${statementDate(x.date)}</td><td>${x.no}</td><td>${x.desc}</td><td class="amt">${statementAmount(x.amount)}</td><td class="amt">${statementAmount(running)}</td></tr>`}).join('');const html=`<!doctype html><html><head><meta charset="utf-8"><title>Supplier Statement</title><style>body{font:14px Arial;padding:24px;color:#222}h2{margin-bottom:4px}.muted{color:#666}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border-bottom:1px solid #ddd;padding:9px;text-align:left}.amt{text-align:right}.sum{display:flex;gap:28px;margin-top:18px;padding:14px;background:#f3f5f7}.sum b{display:block;margin-top:6px}@media print{.noprint{display:none}}</style></head><body><div class="noprint"><button onclick="print()">Print Statement</button><button onclick="window.close()">Close</button></div><h2>Supplier Statement</h2><b>${s.name}</b><div class="muted">${s.phone||''} ${s.idNumber||''}</div><div class="sum"><div>Opening Balance<b>${statementAmount(s.openingBalance||0)}</b></div><div>Total Transactions<b>${statementAmount(events.filter(x=>x.amount>0).reduce((a,x)=>a+x.amount,0))}</b></div><div>Total Credits / Payments<b>${statementAmount(-events.filter(x=>x.amount<0).reduce((a,x)=>a+x.amount,0))}</b></div><div>Closing Balance<b>${statementAmount(running)}</b></div></div><table><thead><tr><th>Date</th><th>Bill / Ref.</th><th>Description</th><th class="amt">Amount</th><th class="amt">Balance</th></tr></thead><tbody><tr><td>—</td><td>—</td><td><b>Opening Balance</b></td><td class="amt">—</td><td class="amt"><b>${statementAmount(s.openingBalance||0)}</b></td></tr>${rows||'<tr><td colspan="5">No transactions</td></tr>'}<tr><td>—</td><td>—</td><td><b>Closing Balance</b></td><td class="amt">—</td><td class="amt"><b>${statementAmount(running)}</b></td></tr></tbody></table><script>window.onload=()=>{}<\/script></body></html>`;const w=window.open('','_blank','width=1000,height=800');if(!w)return alert('Please allow pop-ups to view the statement.');w.document.write(html);w.document.close()}
function editSupplier(i){const v=db.suppliers[i];if(!v)return;const name=prompt('Supplier full name:',v.name);if(name===null)return;const idNumber=prompt('ID Number / NIC:',v.idNumber||'');if(idNumber===null)return;const phone=prompt('Phone:',v.phone||'');if(phone===null)return;const opening=Number(prompt('Opening balance:',v.openingBalance||0));if(!Number.isFinite(opening)||opening<0)return alert('Invalid opening balance.');if(!name.trim())return alert('Name is required.');v.name=name.trim();v.idNumber=idNumber.trim();v.phone=phone.trim();v.openingBalance=opening;v.area=v.area||'';v.category=v.category||'';v.mapLocation=v.mapLocation||'';v.email=v.email||'';v.address=v.address||'';v.description=v.description||'';v.balanceType=v.balanceType||'Payable';db.syncQueue.push({type:'supplier_edit',supplier:{...v},time:Date.now()});save();page('suppliers')}
function deleteSupplier(i){const s=db.suppliers[i]; if(!s)return; if(db.purchases.some(x=>x.supplier===s.name)){alert('This supplier has purchase history. Edit instead of deleting.');return} if(confirm('Delete '+s.name+'?')){db.suppliers.splice(i,1);save();page('suppliers')}}
function adjustAccount(i){const a=db.accounts[i];if(!requirePerm('accounts.adjust'))return; const amount=Number(prompt('Amount to add (positive) or remove (negative) from '+a.name+'\nCurrent: '+money(a.balance),'0')); if(!Number.isFinite(amount)||amount===0)return; if(a.balance+amount<0)return alert('Balance cannot go below zero.'); a.balance+=amount; db.syncQueue.push({type:'account_adjust',accountId:a.id,amount,time:Date.now()}); save(); page('accounts')}
function transferMoney(e){e.preventDefault();if(!requirePerm('accounts.transfer'))return; const from=db.accounts.find(a=>a.id===tfrom.value), to=db.accounts.find(a=>a.id===tto.value), amount=Number(tamount.value); if(!from||!to||from===to)return alert('Select different accounts.'); if(amount<=0||!Number.isFinite(amount))return alert('Invalid amount.'); if(from.balance<amount)return alert('Not enough money in '+from.name+'.'); from.balance-=amount; to.balance+=amount; db.transfers.push({from:from.id,to:to.id,fromName:from.name,toName:to.name,amount,note:tnote.value,date:new Date().toISOString()}); db.syncQueue.push({type:'transfer',from:from.id,to:to.id,amount,note:tnote.value,time:Date.now()}); save(); alert('Transfer completed. '+money(amount)+' moved from '+from.name+' to '+to.name+'.'); page('accounts')}
