function receivePayment(i){if(!requirePerm('customers.paymentReceive'))return;
 const c=db.customers[i]; if(!c)return;
 const credit=db.sales.filter(a=>a.customer===c.name&&a.payment==='Credit').reduce((a,x)=>a+Number(x.total),0);
 const paid=db.customerPayments.filter(a=>a.customer===c.name).reduce((a,x)=>a+Number(x.amount),0);
 const returns=db.customerReturns.filter(a=>a.customer===c.name&&a.method==='Credit Adjustment'&&a.status!=='Cancelled').reduce((a,x)=>a+Number(x.total),0); const balance=Math.max(0,Number(c.openingBalance||0)+credit-paid-returns);
 if(balance<=0){alert('No outstanding balance for '+c.name+'.');return}
 const amount=Number(prompt('Payment received from '+c.name+'\nOutstanding: '+money(balance)+'\n\nEnter amount:',balance));
 if(!Number.isFinite(amount)||amount<=0)return;
 if(amount>balance){alert('Payment cannot exceed outstanding balance.');return}
 const accName=db.accounts.map(a=>a.name).join(' / '); const accChoice=prompt('Receive into account:\n'+db.accounts.map((a,n)=>`${n+1}. ${a.name} (${money(a.balance)})`).join('\n')+'\n\nEnter account number:', '1'); const ai=Number(accChoice)-1; const acc=db.accounts[ai]; if(!acc){alert('Invalid account.');return} acc.balance=Number(acc.balance)+amount;
 db.customerPayments.push({id:'CP-'+Date.now(),customer:c.name,amount,accountId:acc.id,date:new Date().toISOString(),createdBy:currentUser()?.name||'Unknown',createdByUsername:currentUser()?.username||''});
 db.syncQueue.push({type:'customer_payment',customer:c.name,amount,accountId:acc.id,time:Date.now()});
 save(); page('customers');
}
function paymentAccount(p){return db.accounts.find(a=>a.id===p.accountId)}
function editCustomerPayment(i){if(!requirePerm('customers.paymentEdit'))return;const p=db.customerPayments[i];if(!p)return;const c=db.customers.find(x=>x.name===p.customer);if(!c)return;const oldAcc=paymentAccount(p);if(!oldAcc)return alert('Original account not found.');const oldAmount=Number(p.amount||0);const credit=db.sales.filter(a=>a.status!=='Cancelled'&&a.customer===p.customer&&a.payment==='Credit').reduce((a,x)=>a+Number(x.total),0);const returns=db.customerReturns.filter(a=>a.status!=='Cancelled'&&a.customer===p.customer&&a.method==='Credit Adjustment').reduce((a,x)=>a+Number(x.total),0);const otherPaid=db.customerPayments.filter((x,j)=>j!==i&&x.customer===p.customer).reduce((a,x)=>a+Number(x.amount),0);const max= Math.max(0,Number(c.openingBalance||0)+credit-otherPaid-returns);const amount=Number(prompt('Edit payment amount for '+p.customer+'\nMaximum allowed: '+money(max),' '+oldAmount));if(!Number.isFinite(amount)||amount<=0||amount>max)return alert('Invalid payment amount.');const choice=Number(prompt('Receive into account:\n'+db.accounts.map((a,n)=>`${n+1}. ${a.name} (${money(a.balance)})`).join('\n')+'\n\nEnter account number:',String(Math.max(1,db.accounts.findIndex(a=>a.id===p.accountId)+1))))-1;const newAcc=db.accounts[choice];if(!newAcc)return alert('Invalid account.');oldAcc.balance+=oldAmount;if(newAcc!==oldAcc&&Number(newAcc.balance)<amount){oldAcc.balance-=oldAmount;return alert('Not enough money in '+newAcc.name+'.');}newAcc.balance-=amount;p.amount=amount;p.accountId=newAcc.id;p.editedAt=new Date().toISOString();db.syncQueue.push({type:'customer_payment_edit',payment:{...p},time:Date.now()});save();page('customers')}
function deleteCustomerPayment(i){if(!requirePerm('customers.paymentDelete'))return;const p=db.customerPayments[i];if(!p)return;const acc=paymentAccount(p);if(!acc)return alert('Payment account not found.');if(!confirm('Delete this customer payment of '+money(p.amount)+'? The received amount will be reversed from '+acc.name+'.'))return;if(Number(acc.balance)<Number(p.amount)){return alert('Cannot delete: '+acc.name+' balance is lower than this payment.');}acc.balance-=Number(p.amount);db.customerPayments.splice(i,1);db.syncQueue.push({type:'customer_payment_delete',payment:{...p},time:Date.now()});save();page('customers')}
function editSupplierPayment(i){if(!requirePerm('suppliers.paymentEdit'))return;const p=db.supplierPayments[i];if(!p)return;const oldAcc=paymentAccount(p);if(!oldAcc)return alert('Original account not found.');const oldAmount=Number(p.amount||0);const s=db.suppliers.find(x=>x.name===p.supplier);if(!s)return;const credit=db.purchases.filter(a=>a.supplier===p.supplier&&a.payment==='Credit').reduce((a,x)=>a+Number(x.total),0);const returns=db.supplierReturns.filter(a=>a.status!=='Cancelled'&&a.supplier===p.supplier&&a.method==='Credit Adjustment').reduce((a,x)=>a+Number(x.total),0);const otherPaid=db.supplierPayments.filter((x,j)=>j!==i&&x.supplier===p.supplier).reduce((a,x)=>a+Number(x.amount),0);const max=Math.max(0,Number(s.openingBalance||0)+credit-otherPaid-returns);const amount=Number(prompt('Edit payment amount to '+p.supplier+'\nMaximum allowed: '+money(max),String(oldAmount)));if(!Number.isFinite(amount)||amount<=0||amount>max)return alert('Invalid payment amount.');const choice=Number(prompt('Pay from account:\n'+db.accounts.map((a,n)=>`${n+1}. ${a.name} (${money(a.balance)})`).join('\n')+'\n\nEnter account number:',String(Math.max(1,db.accounts.findIndex(a=>a.id===p.accountId)+1))))-1;const newAcc=db.accounts[choice];if(!newAcc)return alert('Invalid account.');oldAcc.balance+=oldAmount;if(newAcc!==oldAcc&&Number(newAcc.balance)<amount){oldAcc.balance-=oldAmount;return alert('Not enough money in '+newAcc.name+'.');}newAcc.balance-=amount;p.amount=amount;p.accountId=newAcc.id;p.editedAt=new Date().toISOString();db.syncQueue.push({type:'supplier_payment_edit',payment:{...p},time:Date.now()});save();page('suppliers')}
function deleteSupplierPayment(i){if(!requirePerm('suppliers.paymentDelete'))return;const p=db.supplierPayments[i];if(!p)return;const acc=paymentAccount(p);if(!acc)return alert('Payment account not found.');if(!confirm('Delete this supplier payment of '+money(p.amount)+'? The paid amount will be returned to '+acc.name+'.'))return;acc.balance+=Number(p.amount);db.supplierPayments.splice(i,1);db.syncQueue.push({type:'supplier_payment_delete',payment:{...p},time:Date.now()});save();page('suppliers')}
let currentStatementCustomer=0;
let statementFrom='',statementTo='';
function statement(i){ currentStatementCustomer=i; statementFrom=''; statementTo=''; renderCustomerStatement(); }
function statementAmount(n){return Number(n||0).toLocaleString('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2})}
function statementDate(v){return v?new Date(v).toLocaleDateString('en-GB'):'—'}
function statementFiltered(v){const d=new Date(v);if(statementFrom&&d<new Date(statementFrom+'T00:00:00'))return false;if(statementTo&&d>new Date(statementTo+'T23:59:59.999'))return false;return true}
function renderCustomerStatement(){
 const c=db.customers[currentStatementCustomer]; if(!c)return page('customers');
 const baseOpening=Number(c.openingBalance||0);
 const events=[];
 const salesByInvoice={};
 db.sales.filter(x=>x.status!=='Cancelled'&&x.customer===c.name).forEach(x=>{
   const key=x.invoice||x.id;
   if(!salesByInvoice[key])salesByInvoice[key]={date:x.date,no:key,desc:x.payment==='Cash'?'Cash Sale':'Credit Sale',amount:0,paid:0,payment:x.payment,kind:'sale'};
   salesByInvoice[key].amount+=Number(x.total||0); salesByInvoice[key].paid=Math.max(salesByInvoice[key].paid,Number(x.paidNow||0));
 });
 Object.values(salesByInvoice).forEach(x=>{events.push({date:x.date,no:x.no,desc:x.desc,amount:x.amount,kind:'sale'});const paid=x.payment==='Cash'?x.amount:Math.min(x.amount,x.paid);if(paid>0)events.push({date:x.date,no:'PAY-'+x.no,desc:'Paid at Sale',amount:-paid,kind:'payment'});});
 db.customerReturns.filter(x=>x.status!=='Cancelled'&&x.customer===c.name&&x.method==='Credit Adjustment').forEach(x=>events.push({date:x.date,no:x.billNo||x.id,desc:'Customer Return',amount:-Number(x.total||0),kind:'return'}));
 db.customerPayments.filter(x=>x.customer===c.name).forEach(x=>events.push({date:x.date,no:x.id||'PAYMENT',desc:'Payment Received',amount:-Number(x.amount||0),kind:'payment'}));
 events.sort((a,b)=>new Date(a.date)-new Date(b.date)||String(a.no).localeCompare(String(b.no)));
 const before=events.filter(x=>{if(!statementFrom)return false;return new Date(x.date)<new Date(statementFrom+'T00:00:00')}).reduce((a,x)=>a+x.amount,0);
 let opening=baseOpening+before;
 const visible=events.filter(x=>statementFiltered(x.date));
 let running=opening;
 const rows=visible.map(x=>{running+=x.amount;return `<tr><td>${statementDate(x.date)}</td><td>${x.no}</td><td>${x.desc}</td><td class="amt">${statementAmount(x.amount)}</td><td class="amt">${statementAmount(running)}</td></tr>`}).join('');
 const totalDebit=visible.filter(x=>x.amount>0).reduce((a,x)=>a+x.amount,0), totalCredit=Math.abs(visible.filter(x=>x.amount<0).reduce((a,x)=>a+x.amount,0));
 const closing=running;
 const titleRange=statementFrom||statementTo?`${statementFrom?statementDate(statementFrom):'—'} - ${statementTo?statementDate(statementTo):'—'}`:'All transactions';
 const ctn=document.getElementById('content');
 ctn.innerHTML=`<div class="page statement-page">
 <div class="statement-toolbar no-print"><button class="secondary" onclick="page('customers')">← Back</button><button class="secondary" onclick="window.print()">🖨️ Print</button></div>
 <div class="panel statement-card">
  <div class="statement-header"><div><h2>Customer Statement</h2><div class="statement-name">${c.name}${c.idNumber?' ['+c.idNumber+']':''}</div></div><div class="statement-range"><b>Date:</b><br>${titleRange}</div></div>
  <div class="statement-filters no-print"><div><label>From Date</label><input id="stmtFrom" type="date" value="${statementFrom}" onchange="statementFrom=this.value;renderCustomerStatement()"></div><div><label>To Date</label><input id="stmtTo" type="date" value="${statementTo}" onchange="statementTo=this.value;renderCustomerStatement()"></div><button class="secondary" onclick="statementFrom='';statementTo='';renderCustomerStatement()">All</button></div>
  <div class="statement-summary"><div><span>Opening</span><b>${statementAmount(opening)}</b></div><div><span>Charges</span><b>${statementAmount(totalDebit)}</b></div><div><span>Credits / Payments</span><b>${statementAmount(totalCredit)}</b></div><div><span>Closing</span><b>${statementAmount(closing)}</b></div></div>
  <div class="table-scroll"><table class="statement-table"><thead><tr><th>Date</th><th>No.</th><th>Description</th><th class="amt">Amount</th><th class="amt">Balance</th></tr></thead><tbody><tr class="opening-row"><td>${statementFrom?statementDate(statementFrom):'—'}</td><td>—</td><td><b>Opening</b></td><td class="amt">—</td><td class="amt"><b>${statementAmount(opening)}</b></td></tr>${rows||'<tr><td colspan="5" class="empty">No transactions in selected period</td></tr>'}<tr class="closing-row"><td>${statementTo?statementDate(statementTo):'—'}</td><td>—</td><td><b>Closing</b></td><td class="amt">—</td><td class="amt"><b>${statementAmount(closing)}</b></td></tr></tbody></table></div>
 </div></div>`;
}
document.addEventListener('input',e=>{if(e.target&&e.target.id==='saleShipping')updateShippingCount()});

function printMyDailyReport(){if(!requirePerm('userReport.print'))return;window.print()}
function exportActivityLog(){if(!requirePerm('activity.export'))return;const rows=[['Date','User','Action','Details'],...(db.activityLog||[]).map(x=>[new Date(x.date).toLocaleString(),x.user,x.action,x.details||''])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='ruhi-mobile-activity-log.csv';a.click()}
function clearActivityLog(){if(!requirePerm('activity.clear'))return;if(!confirm('Clear all activity log records?'))return;db.activityLog=[];save();page('activity')}
function exportReportsCSV(){const from=window.reportFrom||'',to=window.reportTo||'';const filtered=(date)=>{if(!date)return true;const d=new Date(date);if(from&&d<new Date(from+'T00:00:00'))return false;if(to&&d>new Date(to+'T23:59:59.999'))return false;return true};const rows=[['Date','Type','Description','Account','In','Out']];buildTransactions().filter(x=>filtered(x.date)).forEach(t=>rows.push([new Date(t.date).toLocaleString(),t.type,t.desc,t.account||'',t.in||0,t.out||0]));const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='ruhi-mobile-report.csv';a.click()}
